d","headers","Accept","window","g_ck","ok","errorData","json","Error","error","message","status","result","console","get","sysId","create","data","body","JSON","stringify","caller_id","update","delete","insertStyle","css","tagName","style","document","createElement","setAttribute","innerHTML","head","appendChild","link","IncidentList","incidents","onEdit","onRefresh","service","handleDelete","incident","confirm","number","display_value","sys_id","value","alert","_jsx","div","data-source-loc","className","length","children","table","thead","_jsxs","tr","th","tbody","map","shortDesc","short_description","state","impact","openedAt","opened_at","td","span","getStateClass","getImpactClass","button","onClick","aria-label","IncidentForm","onSubmit","onCancel","isEditing","formData","setFormData","useState","description","useEffect","handleChange","e","name","target","prev","h2","type","form","preventDefault","label","htmlFor","input","id","onChange","required","maxLength","textarea","rows","select","option","___$insertStyle","rootElement","getElementById","ReactDOM","createRoot","render","React","StrictMode","setIncidents","loading","setLoading","showForm","setShowForm","selectedIncident","setSelectedIncident","setError","incidentService","useMemo","refreshIncidents","err","handleFormSubmit","header","h1","App"],"ignoreList":[],"sources":["../../src/client/services/IncidentService.js","../../___$insertStyle","../../src/client/components/IncidentList.jsx","../../src/client/components/IncidentForm.jsx","../../src/client/components/IncidentList.css","../../src/client/components/IncidentForm.css","../../src/client/app.css","../../src/client/main.jsx","../../src/client/app.jsx"],"sourcesContent":["export class IncidentService {
    constructor() {
        this.tableName = 'incident'
    }

    // Return all incidents
    async list() {
        try {
            const searchParams = new URLSearchParams()
            searchParams.set('sysparm_display_value', 'all')
            searchParams.set('sysparm_fields', 'sys_id,number,short_description,description,state,impact,opened_at')
            searchParams.set('sysparm_query', 'ORDERBYDESCopened_at')

            const response = await fetch(`/api/now/table/${this.tableName}?${searchParams.toString()}`, {
                method: 'GET',
                headers: {
                    Accept: 'application/json',
                    'X-UserToken': window.g_ck,
                },
            })

            if (!response.ok) {
                const errorData = await response.json()
                throw new Error(errorData.error?.message || `HTTP error ${response.status}`)
            }

            const { result } = await response.json()
            return result || []
        } catch (error) {
            console.error('Error fetching incidents:', error)
            throw error
        }
    }

    // Get a single incident by sys_id
    async get(sysId) {
        try {
            const searchParams = new URLSearchParams()
            searchParams.set('sysparm_display_value', 'all')

            const response = await fetch(`/api/now/table/${this.tableName}/${sysId}?${searchParams.toString()}`, {
                method: 'GET',
                headers: {
                    Accept: 'application/json',
                    'X-UserToken': window.g_ck,
                },
            })

            if (!response.ok) {
                const errorData = await response.json()
                throw new Error(errorData.error?.message || `HTTP error ${response.status}`)
            }

            const { result } = await response.json()
            return result
        } catch (error) {
            console.error(`Error fetching incident ${sysId}:`, error)
            throw error
        }
    }

    // Create a new incident
    async create(data) {
        try {
            const response = await fetch(`/api/now/table/${this.tableName}`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    Accept: 'application/json',
                    'X-UserToken': window.g_ck,
                },
                body: JSON.stringify({
                    ...data,
                    caller_id: '6816f79cc0a8016401c5a33be04be441',
                }),
            })

            if (!response.ok) {
                const errorData = await response.json()
                throw new Error(errorData.error?.message || `HTTP error ${response.status}`)
            }

            return response.json()
        } catch (error) {
            console.error('Error creating incident:', error)
            throw error
        }
    }

    // Update an incident
    async update(sysId, data) {
        try {
            const response = await fetch(`/api/now/table/${this.tableName}/${sysId}`, {
                method: 'PATCH',
                headers: {
                    'Content-Type': 'application/json',
                    Accept: 'application/json',
                    'X-UserToken': window.g_ck,
                },
                body: JSON.stringify(data),
            })

            if (!response.ok) {
                const errorData = await response.json()
                throw new Error(errorData.error?.message || `HTTP error ${response.status}`)
            }

            return response.json()
        } catch (error) {
            console.error(`Error updating incident ${sysId}:`, error)
            throw error
        }
    }

    // Delete an incident
    async delete(sysId) {
        try {
            const response = await fetch(`/api/now/table/${this.tableName}/${sysId}`, {
                method: 'DELETE',
                headers: {
                    Accept: 'application/json',
                    'X-UserToken': window.g_ck,
                },
            })

            if (!response.ok) {
                const errorData = await response.json()
                throw new Error(errorData.error?.message || `HTTP error ${response.status}`)
            }

            return response.ok
        } catch (error) {
            console.error(`Error deleting incident ${sysId}:`, error)
            throw error
        }
    }
}
","export default function insertStyle(css, tagName = "style") {
    if (!css || typeof window === "undefined")
        return;
    if (tagName === "style") {
        const style = document.createElement("style");
        style.setAttribute("type", "text/css");
        style.innerHTML = css;
        document.head.appendChild(style);
    }
    else if (tagName === "link") {
        const link = document.createElement("link");
        link.setAttribute("rel", "stylesheet");
        link.setAttribute("href", css);
        document.head.appendChild(link);
    }
    return css;
}","import React from 'react'
import './IncidentList.css'

export default function IncidentList({ incidents, onEdit, onRefresh, service }) {
    const handleDelete = async (incident) => {
        if (!confirm(`Are you sure you want to delete ${incident.number.display_value}?`)) {
            return
        }

        try {
            const sysId = typeof incident.sys_id === 'object' ? incident.sys_id.value : incident.sys_id
            await service.delete(sysId)
            onRefresh()
        } catch (error) {
            console.error('Failed to delete incident:', error)
            alert('Failed to delete incident: ' + (error.message || 'Unknown error'))
        }
    }

    const getStateClass = (state) => {
        const stateValue = typeof state === 'object' ? state.display_value : state

        switch (stateValue) {
            case 'New':
                return 'state-new'
            case 'In Progress':
                return 'state-in-progress'
            case 'On Hold':
                return 'state-on-hold'
            case 'Resolved':
                return 'state-resolved'
            case 'Closed':
                return 'state-closed'
            default:
                return ''
        }
    }

    const getImpactClass = (impact) => {
        const impactValue = typeof impact === 'object' ? impact.value : impact

        switch (impactValue) {
            case '1':
                return 'impact-high'
            case '2':
                return 'impact-medium'
            case '3':
                return 'impact-low'
            default:
                return ''
        }
    }

    return (
        <div className="incident-list">
            {incidents.length === 0 ? (
                <div className="no-incidents">No incidents found</div>
            ) : (
                <table>
                    <thead>
                        <tr>
                            <th>Number</th>
                            <th>Description</th>
                            <th>State</th>
                            <th>Impact</th>
                            <th>Opened</th>
                            <th>Actions</th>
                        </tr>
                    </thead>
                    <tbody>
                        {incidents.map((incident) => {
                            // Extract primitive values from potential objects
                            const number =
                                typeof incident.number === 'object' ? incident.number.display_value : incident.number
                            const shortDesc =
                                typeof incident.short_description === 'object'
                                    ? incident.short_description.display_value
                                    : incident.short_description
                            const state =
                                typeof incident.state === 'object' ? incident.state.display_value : incident.state
                            const impact =
                                typeof incident.impact === 'object' ? incident.impact.display_value : incident.impact
                            const openedAt =
                                typeof incident.opened_at === 'object'
                                    ? incident.opened_at.display_value
                                    : incident.opened_at

                            return (
                                <tr key={typeof incident.sys_id === 'object' ? incident.sys_id.value : incident.sys_id}>
                                    <td>{number}</td>
                                    <td>{shortDesc}</td>
                                    <td>
                                        <span className={`state-badge ${getStateClass(incident.state)}`}>{state}</span>
                                    </td>
                                    <td>
                                        <span className={`impact-badge ${getImpactClass(incident.impact)}`}>
                                            {impact}
                                        </span>
                                    </td>
                                    <td>{openedAt}</td>
                                    <td>
                                        <div className="action-buttons">
                                            <button
                                                className="edit-button"
                                                onClick={() => onEdit(incident)}
                                                aria-label={`Edit incident ${number}`}
                                            >
                                                Edit
                                            </button>
                                            <button
                                                className="delete-button"
                                                onClick={() => handleDelete(incident)}
                                                aria-label={`Delete incident ${number}`}
                                            >
                                                Delete
                                            </button>
                                        </div>
                                    </td>
                                </tr>
                            )
                        })}
                    </tbody>
                </table>
            )}
        </div>
    )
}
","import React, { useState, useEffect } from 'react'
import './IncidentForm.css'

export default function IncidentForm({ incident, onSubmit, onCancel }) {
    const isEditing = !!incident

    // Initialize form state
    const [formData, setFormData] = useState({
        short_description: '',
        description: '',
        state: '1',
        impact: '2',
    })

    // Load incident data if editing
    useEffect(() => {
        if (incident) {
            // Extract primitive values from potential objects
            const shortDesc =
                typeof incident.short_description === 'object'
                    ? incident.short_description.value
                    : incident.short_description
            const description =
                typeof incident.description === 'object' ? incident.description.value : incident.description
            const state = typeof incident.state === 'object' ? incident.state.value : incident.state
            const impact = typeof incident.impact === 'object' ? incident.impact.value : incident.impact

            setFormData({
                short_description: shortDesc || '',
                description: description || '',
                state: state || '1',
                impact: impact || '2',
            })
        }
    }, [incident])

    const handleChange = (e) => {
        const { name, value } = e.target
        setFormData((prev) => ({
            ...prev,
            [name]: value,
        }))
    }

    const handleSubmit = (e) => {
        e.preventDefault()
        onSubmit(formData)
    }

    return (
        <div className="form-overlay">
            <div className="form-container">
                <div className="form-header">
                    <h2>{isEditing ? `Edit ${incident.number.display_value}` : 'Create New Incident'}</h2>
                    <button type="button" className="close-button" onClick={onCancel}>
                        ×
                    </button>
                </div>
                <form onSubmit={handleSubmit}>
                    <div className="form-group">
                        <label htmlFor="short_description">Short Description *</label>
                        <input
                            type="text"
                            id="short_description"
                            name="short_description"
                            value={formData.short_description}
                            onChange={handleChange}
                            required
                            maxLength={160}
                        />
                    </div>

                    <div className="form-group">
                        <label htmlFor="description">Description</label>
                        <textarea
                            id="description"
                            name="description"
                            value={formData.description}
                            onChange={handleChange}
                            rows={5}
                            maxLength={4000}
                        />
                    </div>

                    <div className="form-row">
                        <div className="form-group">
                            <label htmlFor="state">State</label>
                            <select id="state" name="state" value={formData.state} onChange={handleChange}>
                                <option value="1">New</option>
                                <option value="2">In Progress</option>
                                <option value="3">On Hold</option>
                                <option value="6">Resolved</option>
                                <option value="7">Closed</option>
                            </select>
                        </div>

                        <div className="form-group">
                            <label htmlFor="impact">Impact</label>
                            <select id="impact" name="impact" value={formData.impact} onChange={handleChange}>
                                <option value="1">1 - High</option>
                                <option value="2">2 - Medium</option>
                                <option value="3">3 - Low</option>
                            </select>
                        </div>
                    </div>

                    <div className="form-actions">
                        <button type="button" className="cancel-button" onClick={onCancel}>
                            Cancel
                        </button>
                        <button type="submit" className="submit-button">
                            {isEditing ? 'Update' : 'Create'}
                        </button>
                    </div>
                </form>
            </div>
        </div>
    )
}
